SELECT
 BOOKINGS_MEASURE_KEY,
 BKGS_MEASURE_TRANS_TYPE_CODE,
 BOOKINGS_PROCESS_DATE,
 SALES_TERRITORY_KEY,
 SALES_REP_NUMBER,
 RU_SERVICE_CONTRACT_START_DTM,
 RU_SERVICE_CONTRACT_END_DTM,
 DV_CONTRACT_DURATION,
 DV_ANNUALIZED_FLG,
 DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT,1) AS DV_ANNUALIZED_US_NET_AMT,
 DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT,1) AS DV_MULTIYEAR_US_NET_AMT,
 CASE
  WHEN DV_CONTRACT_DURATION <> 0
   THEN (ANNUAL_AMT+MY_AMT)/DV_CONTRACT_DURATION
  ELSE  0
 END AS PER_MONTH_AMT,
 CAST(TRUNC(DV_CONTRACT_DURATION/12) AS INTEGER) CONTRACT_TERM,
 NULL /*RSTART.FISCAL_YEAR_MONTH_INT*/ CONTRACT_START_MONTH,
 RBKGS.FISCAL_YEAR_WEEK_NUM_INT BOOKINGS_PROCESS_WEEK,
 CASE
  WHEN COALESCE( DV_CONTRACT_DURATION, 501 ) > 500
   THEN 'UNKNOWN'
  /*WHEN RSTART.FISCAL_YEAR_MONTH_INT IS NOT NULL THEN 'Software'  */
  WHEN COALESCE(DV_CONTRACT_DURATION,0) <> 0 /* AND    (MT.RU_SERVICE_CONTRACT_START_DTM IS  NULL  OR  MT.RU_SERVICE_CONTRACT_END_DTM IS  NULL) */
   THEN 'Software'
 /* WHEN DV_CONTRACT_DURATION IS NOT NULL AND ( CAST(MT.RU_SERVICE_CONTRACT_END_DTM AS DATE ) - CAST(MT.RU_SERVICE_CONTRACT_START_DTM AS DATE ) ) = 0 
 THEN  'Software' */
 ELSE 'UNKNOWN'
 END AS ANNUITY_TYPE,
DV_FMV_FLG,
ADJUSTMENT_CODE
 FROM
 {{ source('raw', 'MT_RSTD_BKGS_MEASURE') }} MT
 INNER  JOIN (
   SELECT
    DV_FISCAL_YEAR_QUARTER_NUM_INT,
    PRODUCT_KEY,
    BK_PRDT_ALLCTN_METRIC_CD,
    BK_PRDT_ALLCTN_CLSFCTN_CD,
    ALLOCATION_PCT
    FROM
    {{ source('raw', 'N_PRDT_TO_PRDT_CLSFTN_ALCTN') }}
    WHERE
    RTRIM(  BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
    GROUP BY 1,2,3,4,5) ALCTN
 ON MT.PRODUCT_KEY = ALCTN.PRODUCT_KEY
  AND MT.FISCAL_YEAR_QUARTER_NUMBER_INT = ALCTN.DV_FISCAL_YEAR_QUARTER_NUM_INT

 /*LEFT OUTER  JOIN COMREFVWDB.R_FISCAL_DAY_TO_YEAR RSTART  ON   CAST(MT.RU_SERVICE_CONTRACT_START_DTM AS DATE) =RSTART.CALENDAR_DATE */
INNER JOIN
 {{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RBKGS  ON  MT.BOOKINGS_PROCESS_DATE = RBKGS.CALENDAR_DATE
INNER JOIN
 {{ source('raw', 'R_FISCAL_WEEK_TO_YEAR') }} RWK
ON RWK.FISCAL_YEAR_WEEK_NUM_INT = RBKGS.FISCAL_YEAR_WEEK_NUM_INT
 WHERE
 COLLATE(   SERVICE_FLG, 'en-ci-rtrim') = 'N'
 AND COLLATE( DV_ANNUALIZED_FLG, 'en-ci-rtrim') = 'N'
 AND RTRIM( ALCTN.BK_PRDT_ALLCTN_CLSFCTN_CD)  IN (COLLATE('Software', 'en-ci-rtrim'))
 AND RTRIM( MT.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('POS', 'en-ci-rtrim'), COLLATE('SLS_ADJ', 'en-ci-rtrim'))
 /*AND EDW_UPDATE_DATETIME   > '{{ var('LastExtractDate') }}'*/
AND MT.DV_FISCAL_YEAR_MTH_NUMBER_INT IN (
 SELECT
   FISCAL_YEAR_MTH_NUMBER_INT FROM
   {{ source('raw', 'BKG_PROCESS_DT_CNTRL') }}
 )